import js from '@eslint/js';
import react from 'eslint-plugin-react';
import tseslint from 'typescript-eslint';

/**
 * Flat ESLint config.
 *
 * Uses typescript-eslint directly rather than eslint-config-next's legacy
 * compatibility shim, which does not load cleanly under flat config in this
 * setup. Next.js-specific rules are covered by `next build`, which runs its
 * own lint pass; this config enforces the type-safety rules that matter for
 * an auth tier.
 */
export default tseslint.config(
  {
    ignores: [
      // Generated by `next build`; its triple-slash references are
      // Next's own convention and are not ours to change.
      'next-env.d.ts',

      '.next/**',
      // 📁 **[TASK-1465](../docs/BACKLOG.md) / [B-219](../docs/BUGS.md)** —
      // `next build` writes here so it cannot overwrite the dev server's
      // `.next/`. ⛔ **It is build output and must be ignored for exactly the
      // reason `.next/` is**: without this line the first build after the
      // change put **17,916 lint errors** in front of the gate, none of them
      // anybody's code.
      '.next-build/**',
      'node_modules/**',
      'coverage/**',
      'test-results/**',
      'playwright-report/**',
    ],
  },
  js.configs.recommended,
  ...tseslint.configs.recommended,
  {
    languageOptions: {
      globals: {
        process: 'readonly',
        console: 'readonly',
        crypto: 'readonly',
        fetch: 'readonly',
        window: 'readonly',
      },
    },
    rules: {
      // The auth tier handles credentials; an implicit `any` here is a
      // security review gap, not a style preference.
      '@typescript-eslint/no-explicit-any': 'error',
      '@typescript-eslint/no-unused-vars': ['error', { argsIgnorePattern: '^_' }],
    },
  },
  {
    /**
     * 🔴 **One rule, and it was added because the defect it catches was
     * SHIPPING on Home.**
     *
     * ⛔ **An unbraced `/** … *\/` between two JSX elements is not a comment —
     * it is a text node**, and React renders it verbatim. 📁
     * [`workspace-strip.tsx`](components/home/workspace-strip.tsx) had one, and
     * the mangled `* *` fragments inside it show how it got there: a `{/* … *\/}`
     * comment reflowed until the braces were lost.
     *
     * ⚡ **A parser rule rather than a regex**, and that is the whole reason to
     * reach for the plugin instead of writing a source sweep: **a sweep would
     * have to decide whether a `/**` is inside JSX**, which is a parsing
     * question, and every heuristic answer is either too narrow or too wide.
     * ✅ **`eslint-plugin-react` is already installed** — it arrives with
     * `eslint-config-next` — so this registers a capability the repository has
     * rather than adding a dependency.
     *
     * ⚠️ **Only this rule.** ⛔ **Not `react/recommended`**, which would put
     * hundreds of stylistic findings in front of a gate that currently reports
     * zero — 📁 the same argument `.next-build/**` is ignored for.
     */
    files: ['**/*.tsx'],
    plugins: { react },
    rules: {
      'react/jsx-no-comment-textnodes': 'error',
    },
  },
  {
    files: ['tests/**/*.ts'],
    rules: {
      // Tests deliberately construct malformed inputs to prove they are
      // rejected; `as never` casts are the point, not an oversight.
      '@typescript-eslint/no-unsafe-argument': 'off',
    },
  },
);
